 MockHttpServletRequestBuilder as(MockHttpServletRequestBuilder r,String actor){return r.cookie(new Cookie("gl_session",actor));}
 MockHttpServletRequestBuilder body(MockHttpServletRequestBuilder r,String actor,Object b)throws Exception{return as(r,actor).header("Origin","http://localhost:3000").header("X-Requested-With","getlancer").contentType("application/json").content(json.writeValueAsString(b));}
 JsonNode ok(MockHttpServletRequestBuilder r)throws Exception{return json.readTree(mvc.perform(r).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 Map<String,Object> terms(){return Map.of("engagementId",engagement,"title","Portal care","scope","Bug fixes and small approval workflow improvements.","terms","Includes bounded support. New features need a new agreement. Future billing may be cancelled.","amountMinor",10000,"requestsPerCycle",1,"responseHours",24,"totalCycles",12);}
 UUID draft()throws Exception{return UUID.fromString(ok(body(post("/api/v1/maintenance"),"care-seller",terms())).path("id").asText());}
 String base(UUID offer){return "/api/v1/maintenance/"+offer;}
 UUID accepted()throws Exception{UUID offer=draft();ok(body(post(base(offer)+"/send"),"care-seller",Map.of("consent",true)));String digest=ok(as(get(base(offer)),"care-buyer")).path("digest").asText();ok(body(post(base(offer)+"/accept"),"care-buyer",Map.of("consent",true,"digest",digest)));return offer;}
 JsonNode start(UUID offer)throws Exception{return ok(body(post(base(offer)+"/billing"),"care-buyer",Map.of("billingConsent",true)).header("Idempotency-Key",UUID.randomUUID()));}
 UUID paid()throws Exception{UUID offer=accepted();start(offer);fixture.paid=true;ok(body(post(base(offer)+"/billing/refresh"),"care-buyer",Map.of()));return offer;}
 String sign(String secret,String body)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));}
