 @Test void testModePaidPeriodNeverGrantsRealSupport()throws Exception{UUID offer=accepted(),subscription=UUID.randomUUID(),period=UUID.randomUUID();String digest=db.queryForObject("SELECT digest FROM maintenance_offers WHERE id=?",String.class,offer);db.update("INSERT INTO maintenance_subscriptions(id,engagement_id,offer_id,payer_id,request_key,amount_minor,currency,requests_per_cycle,response_hours,total_cycles,digest,account_id,mode,status,creation_step,plan_state,subscription_state,provider_plan_id,provider_subscription_id,reconciled_at) VALUES(?,?,?,?,?,10000,'INR',1,24,12,?,?,'test','ACTIVE','COMPLETE','CONFIRMED','CONFIRMED',?,?,now())",subscription,engagement,offer,buyer,UUID.randomUUID(),digest,MaintenanceFixture.ACCOUNT,MaintenanceFixture.PLAN,MaintenanceFixture.SUB);db.update("INSERT INTO maintenance_periods(id,subscription_id,provider_invoice_id,payment_id,order_id,amount_minor,currency,period_start,period_end,transfer_key,transfer_state,transfer_id,transfer_status,reconciled_at) VALUES(?,?,?,?,?,10000,'INR',now()-interval '1 day',now()+interval '20 days',?,'CONFIRMED',?,'CREATED',now())",period,subscription,MaintenanceFixture.INVOICE,MaintenanceFixture.PAYMENT,"order_fixture123456",UUID.randomUUID(),MaintenanceFixture.TRANSFER);assertFalse(ok(as(get(base(offer)),"care-buyer")).path("entitlement").path("available").asBoolean());mvc.perform(body(post(base(offer)+"/requests"),"care-buyer",Map.of("title","Real support request","description","A test payment must not authorize any real support work.")).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isConflict());assertEquals(0,db.queryForObject("SELECT count(*) FROM maintenance_requests",Integer.class));}

 @Test void simultaneousRequestsCannotExceedOnePeriodQuota()throws Exception{UUID offer=paid();var pool=Executors.newFixedThreadPool(2);try{var work=new ArrayList<Callable<Integer>>();for(int n=0;n<2;n++){UUID key=UUID.randomUUID();work.add(()->mvc.perform(body(post(base(offer)+"/requests"),"care-buyer",Map.of("title","Concurrent support","description","Only one of these requests may consume the last paid-period slot.")).header("Idempotency-Key",key)).andReturn().getResponse().getStatus());}for(var result:pool.invokeAll(work)){int status=result.get();assertTrue(status==200||status==409,"Unexpected concurrent result "+status);}assertEquals(1,db.queryForObject("SELECT count(*) FROM maintenance_requests",Integer.class));}finally{pool.shutdownNow();}}

